    R x=319.16666 y=350.5 w=136.33333 h=47 rx=3.5 f=#2C2C2C s=#4A4A4A sw=1 fo==1-0.25*down
    T x=336.66666 y=350 w=101.33333 h=48 text=NEXT size=22 weight=bold f=#F2F2F2 align=center valign=middle fit=ellipsis
